int longueur(Object o) {
    // Si o n'est PAS une String, on sort immédiatement.
    if (!(o instanceof String s)) {
        return -1;
    }
    // Si on arrive ici, c'est que o EST une String.
    // Donc s existe et est utilisable dans tout le reste de la méthode,
    // alors qu'on n'est pourtant plus dans le bloc du if.
    return s.length();
}

