void afficher(Object o) {
    if (!(o instanceof String s)) {
        return;
    }
    System.out.println(s);
}

Object o = "  ";

// o instanceof String s teste le type et crée s.
// Le && n'évalue sa droite QUE si la gauche est vraie,
// donc !s.isBlank() n'est examiné que lorsque s existe réellement.
if (o instanceof String s && !s.isBlank()) {
    // On entre ici seulement si o est une String ET non vide/non blanche.
    System.out.println("Texte utile : " + s);
} else {
    System.out.println("Pas une chaine exploitable.");
}
// isBlank() renvoie vrai si la chaine est vide ou ne contient que des espaces.

