final class Point {
    private final int x;
    private final int y;
    Point(int x, int y) { this.x = x; this.y = y; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;          // même objet en mémoire : égal
        if (!(o instanceof Point)) return false; // pas un Point : pas égal
        Point other = (Point) o;             // cast redondant, encore lui
        return x == other.x && y == other.y; // comparaison des champs
    }
}

final class Point {
    private final int x;
    private final int y;
    Point(int x, int y) { this.x = x; this.y = y; }

    @Override
    public boolean equals(Object o) {
        // Un seul test : si o est un Point, la variable other est déjà prête.
        // Grace au flow scoping, other est utilisable à droite du &&.
        return o instanceof Point other
                && x == other.x
                && y == other.y;
        // Note : pas besoin du this == o au début, mais on peut le garder
        // comme petite optimisation si on le souhaite.
    }
}

